import { character as c, type EntitySeed } from "../types";

export const heroes: EntitySeed[] = [
  c("heracles", "Heracles", "hero", "🦁", "Strongest of Mortals", "m", { aliases: ["Hercules", "Herakles", "Alcides"], domains: ["strength", "heroes"], summary: "Son of [[zeus]] and the mortal [[alcmene]], the greatest of the Greek heroes and the lifelong target of Hera's hostility. Driven mad by her, he killed his own children and in atonement performed the [[twelve-labors|Twelve Labours]] for Eurystheus of Mycenae. He died on a pyre on Mount Oeta after putting on a robe smeared with the poisoned blood of the centaur Nessus, and was received on Olympus as a god, with Hebe as his wife." }),
  c("perseus", "Perseus", "hero", "🪞", "Slayer of Medusa", "m", { summary: "Son of [[zeus]] and [[danae|Danaë]], cast adrift in a chest with his mother by his grandfather Acrisius. Sent by Polydectes to fetch the head of [[medusa]], he succeeded with the help of Athena and Hermes and rescued Andromeda from a sea monster on the way home. He later killed Acrisius by accident with a discus, fulfilling the oracle, and was remembered as the founder of Mycenae." }),
  c("theseus", "Theseus", "hero", "🧶", "Hero of Athens", "m", { summary: "Son of [[aegeus]] of Athens (or of Poseidon) and Aethra of Troezen, and the national hero of Athens. He cleared the road to Athens of brigands, killed the [[minotaur]] in the Labyrinth with [[ariadne]]'s help, and then abandoned her on Naxos; his failure to change his black sails drove Aegeus to suicide. Credited with uniting Attica, he died in exile on Scyros, thrown from a cliff by King Lycomedes." }),
  c("jason", "Jason", "hero", "⛵", "Leader of the Argonauts", "m", { aliases: ["Iason"], summary: "Son of Aeson and rightful heir to Iolcus, raised by the centaur Chiron. Sent by the usurper [[pelias]] to fetch the [[golden-fleece|Golden Fleece]], he sailed to Colchis on the Argo and won it with the help of the king's daughter [[medea]]. He later deserted her at Corinth for the king's daughter, with disastrous results, and died when a timber of the rotting Argo fell on him." }),
  c("achilles", "Achilles", "hero", "🛡️", "Best of the Achaeans", "m", { aliases: ["Achilleus", "Akhilleus", "Pelides"], summary: "Son of [[peleus]] and the Nereid [[thetis]], leader of the Myrmidons of Phthia, the greatest Greek warrior at Troy and the central figure of the [[iliad|Iliad]]. His quarrel with Agamemnon over the captive Briseis led him to withdraw from battle until the death of Patroclus, which he avenged by killing Hector. He was killed by an arrow shot by Paris and guided by Apollo; the story that he was vulnerable only in the heel is post-Homeric." }),
  c("odysseus", "Odysseus", "hero", "🧭", "Man of Many Wiles", "m", { aliases: ["Ulysses", "Ulixes"], summary: "King of Ithaca, son of [[laertes]] and Anticleia, husband of [[penelope]] and father of Telemachus. The most cunning of the Greeks at Troy, he devised the Wooden Horse. The [[odyssey|Odyssey]] recounts his ten-year voyage home — the Cyclops Polyphemus, Circe, the land of the dead, seven years with Calypso — ending in the slaughter of Penelope's suitors. A later epic, the Telegony, had him killed unwittingly by Telegonus, his son by Circe." }),
  c("bellerophon", "Bellerophon", "hero", "🐎", "Rider of Pegasus", "m", { aliases: ["Bellerophontes"], summary: "Corinthian hero, son of Glaucus (or of Poseidon) and grandson of [[sisyphus]]. Falsely accused by the wife of King Proetus, he was sent to Iobates of Lycia, who set him to kill the [[chimera]]; he did so mounted on the winged horse [[pegasus]], and went on to defeat the Solymi and the Amazons. When he tried to fly to Olympus he was thrown, and ended his days a wanderer hated by the gods." }),
  c("orpheus", "Orpheus", "hero", "🎻", "Thracian Singer", "m", { summary: "Thracian musician, son of the Muse [[calliope]] and Oeagrus (or Apollo), whose song moved animals, trees and stones. He sailed with the Argonauts and out-sang the Sirens. When his wife [[eurydice]] died he descended to the Underworld and won her release on condition that he not look back; he looked, and lost her. He was torn apart by Thracian maenads, and his head floated, still singing, to Lesbos." }),
  c("atalanta", "Atalanta", "heroine", "🏃‍♀️", "Swift-Footed Huntress", "f", { aliases: ["Atalante"], summary: "Huntress exposed at birth by her father (Iasus in the Arcadian version, Schoeneus in the Boeotian), suckled by a she-bear and raised by hunters. She drew first blood in the [[calydonian-boar-hunt|Calydonian Boar Hunt]] and in some accounts sailed with the Argonauts. She raced her suitors on pain of death until Hippomenes (or Melanion) beat her by dropping three golden apples from Aphrodite; the couple were later turned into lions." }),
  c("meleager", "Meleager", "hero", "🐗", "Prince of Calydon", "m", { aliases: ["Meleagros"], summary: "Son of Oeneus of Calydon and Althaea. The Fates declared he would live only as long as a brand then burning on the hearth, which his mother hid away. He led the [[calydonian-boar-hunt|Calydonian Boar Hunt]], awarded the hide to [[atalanta]], and killed his uncles in the ensuing quarrel, whereupon Althaea burned the brand. In Homer's older version he dies through his mother's curse instead." }),
  c("cadmus", "Cadmus", "hero", "🐉", "Founder of Thebes", "m", { aliases: ["Kadmos"], summary: "Phoenician prince, son of Agenor and brother of [[europa]]. Sent to find his abducted sister, he was told by Delphi to follow a cow instead and founded [[thebes|Thebes]] where it lay down. He killed the dragon of Ares and sowed its teeth, from which sprang the Spartoi, ancestors of the Theban nobility. Husband of [[harmonia]] and, according to Herodotus, bringer of the alphabet to Greece, he ended his life transformed into a serpent in Illyria." }),
  c("oedipus", "Oedipus", "king", "👁️", "King of Thebes", "m", { aliases: ["Oidipous"], summary: "Son of [[laius]] and [[jocasta]], exposed at birth because an oracle foretold he would kill his father, and raised in Corinth. He unknowingly killed Laius at a crossroads, freed Thebes by answering the riddle of the [[sphinx|Sphinx]], and married his mother. In Sophocles he blinds himself on learning the truth and dies an exile at Colonus; in Homer he continues to rule Thebes." }),
  c("diomedes", "Diomedes", "hero", "🏇", "Of the Loud War Cry", "m", { summary: "Son of Tydeus, king of Argos and one of the Epigoni who took Thebes. Among the foremost Greek fighters at Troy, in Iliad 5 he wounds [[aphrodite]] and, with Athena's help, [[ares]] himself. He partnered [[odysseus]] in the night raid on Rhesus and the theft of the Palladium. Later traditions have him driven from Argos to settle in southern Italy." }),
  c("ajax-the-great", "Ajax the Great", "hero", "🧱", "Bulwark of the Achaeans", "m", { aliases: ["Telamonian Ajax", "Aias"], summary: "Son of [[telamon]] of Salamis, the tallest and strongest of the Greeks at Troy after Achilles, known for his tower-like shield. He fought Hector to a draw and carried Achilles' body from the field. When the [[armor-of-achilles|armour of Achilles]] was awarded to Odysseus instead, he went mad, slaughtered a flock of sheep in place of his rivals, and fell on the sword Hector had given him." }),
  c("ajax-the-lesser", "Ajax the Lesser", "hero", "🌩️", "Swift Son of Oileus", "m", { aliases: ["Locrian Ajax", "Oilean Ajax", "Aias"], summary: "Son of Oileus and leader of the Locrians at Troy, a small man but a fast runner and skilled spearman. During the sack he dragged [[cassandra]] from the statue of [[athena]], and the goddess's anger wrecked the returning Greek fleet. He reached a rock and boasted of surviving in spite of the gods, at which Poseidon split the rock and drowned him." }),
  c("patroclus", "Patroclus", "hero", "🫂", "Companion of Achilles", "m", { aliases: ["Patroklos"], summary: "Son of Menoetius of Opus, brought up in Phthia alongside [[achilles]] after killing a playmate in a quarrel over dice. In Iliad 16 he enters battle in Achilles' armour, drives the Trojans from the ships and kills [[sarpedon]], but is struck by Apollo and finished by [[hector]]. His death brings Achilles back into the war." }),
  c("aeneas", "Aeneas", "hero", "🏛️", "Son of Anchises and Aphrodite", "m", { aliases: ["Aineias"], summary: "Trojan prince of the Dardanian line, son of [[anchises]] and [[aphrodite]]. In the Iliad he is twice rescued by gods because he is fated to rule the surviving Trojans. Virgil's [[aeneid|Aeneid]] tells how he carried his father from burning Troy, lost his wife Creusa, and wandered by way of Carthage to Italy, where his descendants would found Rome." }),
  c("castor", "Castor", "hero", "🐴", "Tamer of Horses", "m", { aliases: ["Kastor"], summary: "One of the Dioscuri, twin brother of [[pollux]] and son of [[leda]]; he is usually the mortal twin, fathered by Tyndareus. The brothers sailed with the Argonauts, hunted the Calydonian Boar and recovered their sister Helen from Theseus. Castor was killed in a quarrel with Idas and Lynceus, and Pollux shared his immortality with him. They were patrons of sailors and identified with the constellation Gemini." }),
  c("pollux", "Pollux", "hero", "🥊", "The Boxer", "m", { aliases: ["Polydeuces", "Polydeukes"], summary: "One of the Dioscuri, twin of [[castor]] and in most accounts the immortal son of [[zeus]] and [[leda]]. A champion boxer, he killed the brutal King Amycus of the Bebryces during the voyage of the Argo. When Castor was killed he refused to be immortal alone, and Zeus allowed the twins to spend alternate days on Olympus and in the Underworld." }),
  c("peleus", "Peleus", "hero", "💍", "King of Phthia", "m", { summary: "Son of [[aeacus]] of Aegina, exiled with his brother Telamon for killing their half-brother Phocus. An Argonaut and Calydonian hunter, he became king in Phthia and was granted the Nereid [[thetis]] as his bride after holding her fast through her changes of shape. All the gods attended the [[wedding-of-peleus-and-thetis|wedding]], where Eris threw the apple of discord. He outlived their son Achilles." }),
  c("telamon", "Telamon", "hero", "⚓", "King of Salamis", "m", { summary: "Son of [[aeacus]] and brother of [[peleus]], exiled from Aegina for the killing of Phocus and afterwards king of Salamis. He sailed with the Argonauts, hunted the Calydonian Boar, and joined [[heracles]] in the first sack of Troy, receiving the princess Hesione as his prize. He was father of Ajax the Great by Periboea and of the archer Teucer by Hesione." }),
  c("triptolemus", "Triptolemus", "hero", "🌱", "Teacher of Agriculture", "m", { aliases: ["Triptolemos"], summary: "Prince of Eleusis, in most accounts a son of King Celeus. [[demeter]] gave him seed-corn and a chariot drawn by winged serpents and sent him across the world to teach mankind agriculture. He was a central figure of the Eleusinian Mysteries, and Plato names him among the judges of the dead." }),
  c("orion", "Orion", "hero", "🌌", "The Giant Huntsman", "m", { summary: "Giant hunter of Boeotia, called a son of Poseidon and Euryale, or said to have been born from an ox-hide buried by the childless Hyrieus. Blinded by Oenopion of Chios, he recovered his sight by facing the rising sun. Accounts of his death differ: he was shot by [[artemis]], or stung by a scorpion sent by [[gaia]]. He was placed among the stars, where he still pursues the [[pleiades|Pleiades]]." }),
  c("daedalus", "Daedalus", "mortal", "📐", "Master Craftsman", "m", { aliases: ["Daidalos"], summary: "Athenian craftsman and inventor who fled to Crete after killing his gifted nephew Perdix out of jealousy. For [[minos]] he built the [[labyrinth|Labyrinth]], and for Pasiphaë the wooden cow. Imprisoned, he escaped on wings of feathers and wax, losing his son [[icarus]] on the way, and found refuge with King Cocalus in Sicily." }),
  c("icarus", "Icarus", "mortal", "🪶", "Son of Daedalus", "m", { aliases: ["Ikaros"], summary: "Son of [[daedalus]], imprisoned with his father on Crete. Escaping on wings of feathers and wax, he ignored the warning to keep a middle course and flew too near the sun; the wax melted and he fell into the sea. The Icarian Sea and the island of Icaria, where Heracles is said to have buried him, bear his name." }),
  c("pelops", "Pelops", "king", "🏎️", "King of Pisa", "m", { summary: "Son of [[tantalus]], who butchered him and served him to the gods; they restored him to life with an ivory shoulder in place of the one Demeter had eaten. He won Hippodamia and the kingdom of Pisa by beating her father Oenomaus in a chariot race, having bribed the charioteer Myrtilus, whom he then killed. Myrtilus' dying curse fell on his sons [[atreus]] and Thyestes. The Peloponnese is named after him." }),
  c("tantalus", "Tantalus", "king", "🍑", "King of Sipylus", "m", { aliases: ["Tantalos"], summary: "Lydian king, a son of Zeus admitted to the table of the gods. He abused the privilege — by stealing nectar and ambrosia, betraying divine secrets, or serving the gods his own son [[pelops]]; the sources vary. In [[tartarus|Tartarus]] he stands in water beneath fruit trees, both of which recede when he reaches for them; in other versions a stone hangs forever over his head. He was also father of [[niobe]]." }),
  c("sisyphus", "Sisyphus", "king", "🪨", "King of Corinth", "m", { aliases: ["Sisyphos"], summary: "Son of Aeolus and founder of Ephyra (Corinth), called by Homer the craftiest of men. He revealed Zeus' abduction of Aegina to her father Asopus, put [[thanatos|Death]] in chains, and later talked his way out of the Underworld on the pretext of reproaching his wife for neglecting his funeral rites. His punishment is to roll a boulder up a hill forever, only for it to roll back down. Some called him the true father of Odysseus." }),
  c("narcissus", "Narcissus", "mortal", "🌼", "Son of Cephissus", "m", { aliases: ["Narkissos"], summary: "Beautiful youth of Thespiae in Boeotia, son of the river Cephissus and the nymph Liriope. In Ovid's account he spurned all admirers, among them the nymph [[echo]], and [[nemesis]] caused him to fall in love with his own reflection in a pool; he wasted away and the narcissus flower grew where he died. An earlier version in Conon makes a rejected suitor, Ameinias, the cause of the curse." }),
  c("adonis", "Adonis", "mortal", "🌹", "Beloved of Aphrodite", "m", { summary: "Youth of extraordinary beauty, born from a myrrh tree after his mother Myrrha (or Smyrna) conceived him by her own father, Cinyras or Theias. [[aphrodite]] and [[persephone]] both claimed him, and Zeus divided his year between them. He was killed by a boar while hunting, and the anemone sprang from his blood. His cult, of Near Eastern origin, was marked by the women's festival of the Adonia." }),
  c("actaeon", "Actaeon", "mortal", "🦌", "Hunter of Thebes", "m", { aliases: ["Aktaion"], summary: "Theban hunter, son of Aristaeus and Autonoë and grandson of [[cadmus]], trained by Chiron. In the best-known version he came upon [[artemis]] bathing; she turned him into a stag and he was torn apart by his own hounds. Earlier sources give other offences: courting his aunt Semele, or boasting that he was the better hunter." }),
  c("hippolytus", "Hippolytus", "mortal", "🏇", "Son of Theseus", "m", { aliases: ["Hippolytos"], summary: "Son of [[theseus]] and an Amazon, Hippolyta or Antiope. Devoted to Artemis and to chastity, he slighted Aphrodite, who made his stepmother [[phaedra]] fall in love with him. Rejected, Phaedra accused him of assault; Theseus cursed him, and Poseidon sent a bull from the sea that stampeded his horses and dragged him to his death. The story is the subject of Euripides' Hippolytus." }),
  c("iolaus", "Iolaus", "hero", "🔥", "Nephew and Charioteer of Heracles", "m", { aliases: ["Iolaos"], summary: "Son of Iphicles, the mortal half-brother of [[heracles]], and the hero's charioteer and companion in many labours. He cauterized the necks of the [[hydra|Hydra]] so that new heads could not grow. Later traditions say he led a colony to Sardinia and, briefly restored to youth, killed or captured Eurystheus in defence of Heracles' children." }),
  c("pirithous", "Pirithous", "hero", "🪑", "King of the Lapiths", "m", { aliases: ["Peirithous", "Peirithoos"], summary: "King of the Thessalian Lapiths, son of Ixion (or Zeus) and close friend of [[theseus]]. At his wedding to Hippodamia the drunken [[centaurs]] tried to carry off the women, starting the battle of Lapiths and Centaurs. He helped Theseus abduct the young Helen, then went down to the Underworld to seize [[persephone]] for himself; Hades bound both to seats of stone, and Heracles was able to free only Theseus." }),
  c("telemachus", "Telemachus", "mortal", "🧑", "Son of Odysseus", "m", { aliases: ["Telemachos"], summary: "Son of [[odysseus]] and [[penelope]], an infant when his father left for Troy. The first four books of the Odyssey follow his journey, guided by Athena in the form of Mentor, to Nestor at Pylos and Menelaus at Sparta in search of news. He later fights beside his father against the suitors. The lost Telegony had him marry Circe." }),
  c("zetes", "Zetes", "hero", "🪽", "Winged Son of Boreas", "m", { summary: "One of the Boreads, winged twin sons of the north wind [[boreas]] and the Athenian princess Oreithyia. As Argonauts he and his brother [[calais]] chased the [[harpies|Harpies]] away from the blind seer Phineus. Apollonius says Heracles later killed the twins on Tenos, because they had urged the Argo to sail on without him." }),
  c("calais", "Calais", "hero", "🪽", "Winged Son of Boreas", "m", { aliases: ["Kalais"], summary: "One of the Boreads, winged twin of [[zetes]] and son of [[boreas]] and Oreithyia, daughter of Erechtheus of Athens. With his brother he joined the [[argonauts]] and drove the Harpies from the table of Phineus, pursuing them as far as the Strophades. Both were later killed by Heracles on Tenos, where a pillar on their tomb was said to sway in the north wind." }),
  c("idas", "Idas", "hero", "🏹", "Prince of Messenia", "m", { summary: "Son of Aphareus of Messenia (or of Poseidon) and brother of [[lynceus]]; Homer calls him the strongest man of his day. He carried off Marpessa and drew his bow against [[apollo]] for her; Zeus let her choose, and she chose the mortal. An Argonaut and Calydonian hunter, he killed [[castor]] in a quarrel over cattle (or brides) and was struck down by Zeus' thunderbolt." }),
  c("lynceus", "Lynceus", "hero", "👀", "The Sharp-Sighted", "m", { aliases: ["Lynkeus"], summary: "Messenian prince, son of Aphareus and brother of [[idas]], whose eyesight was so keen he could see through trees and into the earth. He served as lookout on the Argo. In the feud with the Dioscuri he spotted them hiding in a hollow oak, and was killed by [[pollux]]. He is distinct from Lynceus the husband of the Danaid Hypermnestra." }),
  c("argus", "Argus", "hero", "🪚", "Builder of the Argo", "m", { aliases: ["Argos"], summary: "Shipwright who built the [[argo|Argo]] under [[athena]]'s direction, fitting into its prow a speaking timber from the oak of Dodona, and who sailed aboard it as one of the Argonauts. Apollonius calls him a son of Arestor; others make him a son of Phrixus. He is not to be confused with the hundred-eyed Argus Panoptes." }),
  c("hylas", "Hylas", "hero", "🏺", "Companion of Heracles", "m", { summary: "Son of Theiodamas, king of the Dryopes, taken into the household of [[heracles]] as his beloved squire and brought along on the Argo. When the ship put in at Mysia he went to draw water and was pulled into the spring by its nymphs. Heracles searched so long that the [[argonauts]] sailed without him. The people of Cius kept a yearly rite of calling Hylas' name." }),
];

export const women: EntitySeed[] = [
  c("ariadne", "Ariadne", "heroine", "🧵", "Princess of Crete", "f", { aliases: ["Ariadna"], summary: "Daughter of [[minos]] and Pasiphaë. She gave [[theseus]] the ball of thread with which he found his way out of the Labyrinth, and fled with him, only to be left on Naxos. In the usual account [[dionysus]] found and married her there, setting her crown among the stars as Corona Borealis; Homer instead says Artemis killed her on the island of Dia." }),
  c("medea", "Medea", "heroine", "🧪", "Sorceress of Colchis", "f", { aliases: ["Medeia"], summary: "Daughter of [[aeetes|Aeëtes]] of Colchis, granddaughter of Helios, niece of Circe and priestess of Hecate. Her magic won [[jason]] the Golden Fleece; to aid their escape she killed her brother Apsyrtus, and at Iolcus she tricked the daughters of Pelias into butchering their father. When Jason abandoned her at Corinth she killed his new bride and, in [[medea-play|Euripides' play]], her own children, then fled in the chariot of the Sun to Athens." }),
  c("andromeda", "Andromeda", "heroine", "⛓️", "Princess of Aethiopia", "f", { summary: "Daughter of Cepheus and [[cassiopeia]] of Aethiopia. To atone for her mother's boast she was chained to a sea-cliff as an offering to the monster [[cetus]]. [[perseus]], returning with Medusa's head, killed the beast and married her. Their descendants ruled Mycenae and included Heracles; their son Perses was claimed as ancestor of the Persians. She was set among the constellations." }),
  c("danae", "Danaë", "mortal", "🌧️", "Mother of Perseus", "f", { aliases: ["Danae"], summary: "Daughter of [[acrisius]] of Argos, who shut her in a bronze chamber because an oracle said her son would kill him. [[zeus]] came to her as a shower of gold, and she bore [[perseus]]. Acrisius set mother and child adrift in a chest, which came ashore on Seriphos, where the fisherman Dictys sheltered them and King Polydectes pursued her." }),
  c("alcmene", "Alcmene", "mortal", "🌙", "Mother of Heracles", "f", { aliases: ["Alkmene", "Alcmena"], summary: "Daughter of Electryon of Mycenae and wife of [[amphitryon]]. [[zeus]] visited her in her husband's likeness, prolonging the night, and she bore twins: [[heracles]] by Zeus and Iphicles by Amphitryon. Hera had the goddess of childbirth delay the delivery. After her death she was taken to the Isles of the Blessed and married to Rhadamanthus." }),
  c("leda", "Leda", "queen", "🦢", "Queen of Sparta", "f", { summary: "Daughter of Thestius of Aetolia and wife of [[tyndareus]] of Sparta. [[zeus]] came to her in the form of a swan. She was mother of Helen, Clytemnestra, Castor and Pollux, though which were children of Zeus varies; usually Helen and Pollux. In another tradition [[nemesis]] laid the egg from which Helen hatched, and Leda merely reared her." }),
  c("europa", "Europa", "mortal", "🐂", "Princess of Phoenicia", "f", { aliases: ["Europe"], summary: "Daughter of Agenor of Tyre (of Phoenix in Homer) and sister of [[cadmus]]. [[zeus]], in the form of a white bull, carried her over the sea to [[crete|Crete]], where she bore Minos, Rhadamanthus and, in most accounts, Sarpedon. She afterwards married the Cretan king Asterion, who raised her sons. The continent was said to take its name from her." }),
  c("semele", "Semele", "mortal", "🔥", "Mother of Dionysus", "f", { aliases: ["Thyone"], summary: "Daughter of [[cadmus]] and Harmonia of Thebes, loved by [[zeus]]. The disguised Hera persuaded her to ask Zeus to appear in his full glory, and she was consumed by his lightning; Zeus rescued the unborn [[dionysus]] and sewed him into his thigh. Dionysus later brought her up from the Underworld to Olympus, where she was called Thyone." }),
  c("antiope", "Antiope", "mortal", "🌾", "Mother of Amphion and Zethus", "f", { summary: "Theban princess, daughter of Nycteus (of the river Asopus in Homer), seduced by [[zeus]] in the form of a satyr. Her twin sons [[amphion]] and [[zethus]] were exposed on Mount Cithaeron and raised by a herdsman, while she was held and tormented by her uncle Lycus and his wife Dirce. The grown twins avenged her by tying Dirce to a bull. She is distinct from the Amazon Antiope." }),
  c("io", "Io", "mortal", "🐄", "Priestess of Hera at Argos", "f", { summary: "Daughter of the river-god [[inachus]] and priestess of Hera, loved by Zeus and turned into a white heifer — by him to hide her, or by Hera in anger. Hera set the hundred-eyed Argus to guard her and, after [[hermes]] killed him, a gadfly to drive her across the world; the Ionian Sea and the Bosporus recall her passage. In Egypt she regained her form and bore [[epaphus]], and was identified with Isis." }),
  c("penelope", "Penelope", "queen", "🧶", "Wise Penelope", "f", { aliases: ["Penelopeia"], summary: "Daughter of Icarius of Sparta, cousin of Helen, wife of [[odysseus]] and mother of [[telemachus]]. During her husband's twenty-year absence she held off more than a hundred suitors, for three years by weaving a shroud for Laertes and unravelling it each night. She set the contest of the bow that Odysseus won, and tested the returned stranger with the secret of their bed before accepting him." }),
  c("jocasta", "Jocasta", "queen", "👑", "Queen of Thebes", "f", { aliases: ["Epicaste", "Iocaste"], summary: "Daughter of Menoeceus and sister of [[creon]], wife of [[laius]] and then, unknowingly, of her own son [[oedipus]], to whom she bore Eteocles, Polynices, Antigone and Ismene. In Homer (as Epicaste) and Sophocles she hangs herself when the truth comes out; in Euripides' Phoenician Women she lives on and kills herself over the bodies of her sons." }),
  c("antigone", "Antigone", "heroine", "⚰️", "Daughter of Oedipus", "f", { summary: "Daughter of [[oedipus]] and [[jocasta]], who in Sophocles guides her blind father into exile at Colonus. After her brothers killed each other in the war of the [[seven-against-thebes|Seven against Thebes]], she defied Creon's decree and gave Polynices burial rites. Walled up alive in a tomb, she hanged herself; Creon's son Haemon, her betrothed, and his wife Eurydice killed themselves in turn." }),
  c("phaedra", "Phaedra", "queen", "💔", "Queen of Athens", "f", { aliases: ["Phaidra"], summary: "Daughter of [[minos]] and Pasiphaë, sister of Ariadne and wife of [[theseus]], to whom she bore Acamas and Demophon. Through Aphrodite's doing she fell in love with her stepson [[hippolytus]]. When he rejected her she hanged herself, leaving a letter accusing him of rape, which led Theseus to call down the curse that killed his son." }),
  c("pasiphae", "Pasiphaë", "queen", "🐄", "Queen of Crete", "f", { aliases: ["Pasiphae"], summary: "Daughter of [[helios]] and the Oceanid Perse, sister of Circe and Aeëtes, and wife of [[minos]]. When Minos kept back the bull he had promised to Poseidon, the god made her desire it; Daedalus built her a hollow wooden cow, and she bore the [[minotaur]]. Her other children included Ariadne, Phaedra, Androgeus and Deucalion. Like her kin she was skilled in sorcery." }),
  c("hippolyta", "Hippolyta", "queen", "🎗️", "Queen of the Amazons", "f", { aliases: ["Hippolyte"], summary: "Queen of the [[amazons]] and daughter of [[ares]], who gave her the war-belt that [[heracles]] was sent to fetch as his ninth labour. In most accounts she was willing to hand it over, but Hera stirred the Amazons to attack and Heracles killed her. Other versions have her (or her sister Antiope) carried off by Theseus and become the mother of Hippolytus." }),
  c("penthesilea", "Penthesilea", "queen", "🏇", "Amazon Queen at Troy", "f", { aliases: ["Penthesileia"], summary: "Amazon queen, daughter of [[ares]] and Otrera, who brought her warriors to Troy's aid after the death of Hector — some say seeking purification for accidentally killing her sister. Her story was told in the lost epic Aethiopis. She was killed by [[achilles]], who grieved over her beauty and killed Thersites for mocking him about it." }),
  c("deianira", "Deianira", "mortal", "👘", "Wife of Heracles", "f", { aliases: ["Deianeira"], summary: "Daughter of Oeneus of Calydon (or of Dionysus) and sister of Meleager; [[heracles]] won her by wrestling the river-god [[achelous]]. The dying centaur [[nessus]], shot for assaulting her, persuaded her to keep his blood as a love charm. When Heracles brought home the captive Iole she sent him a robe smeared with it; it burned him fatally, and she killed herself. Sophocles dramatized the story in the Women of Trachis." }),
  c("megara", "Megara", "mortal", "🏺", "First Wife of Heracles", "f", { summary: "Daughter of [[creon]] of Thebes, given in marriage to [[heracles]] as a reward for defeating the Minyans of Orchomenus. In a madness sent by Hera, Heracles killed their children — and, in Euripides' Heracles, Megara as well. In other accounts she survived and was afterwards married to his nephew [[iolaus]]." }),
  c("niobe", "Niobe", "queen", "😭", "Queen of Thebes", "f", { summary: "Daughter of [[tantalus]] and wife of [[amphion]] of Thebes. She boasted that her many children — six sons and six daughters in Homer, seven of each in most later authors — made her superior to [[leto]], who had only two. Apollo and Artemis shot them down. Niobe was turned to stone on Mount Sipylus in Lydia, where a rock face was said to weep." }),
  c("arachne", "Arachne", "mortal", "🕷️", "Weaver of Lydia", "f", { summary: "Lydian weaver, daughter of the dyer Idmon of Colophon, known chiefly from Ovid's [[metamorphoses|Metamorphoses]]. She refused to credit [[athena]] for her skill and challenged her to a contest; her tapestry, depicting the gods' seductions of mortals, was flawless. The goddess tore it up and struck her, Arachne hanged herself, and Athena turned her into a spider." }),
  c("cassiopeia", "Cassiopeia", "queen", "💺", "Queen of Aethiopia", "f", { aliases: ["Cassiepeia", "Kassiopeia"], summary: "Wife of Cepheus of Aethiopia and mother of [[andromeda]]. She boasted that she (or her daughter) was more beautiful than the [[nereids|Nereids]], and Poseidon sent a flood and the sea monster [[cetus]]; the oracle of Ammon demanded Andromeda as the price of relief. She was placed among the stars on a throne that, as a punishment, turns upside down for part of the year." }),
  c("pandora", "Pandora", "mortal", "🏺", "The First Woman", "f", { summary: "In Hesiod, the first woman, moulded from earth by [[hephaestus]] on Zeus' orders as a punishment for mankind after Prometheus' theft of fire, and endowed with gifts by all the gods. [[epimetheus]] accepted her despite his brother's warning. She opened a great [[pandoras-jar|storage jar]] and released evils into the world, leaving only Hope inside. The familiar 'box' comes from a sixteenth-century mistranslation by Erasmus." }),
  c("helen", "Helen", "queen", "🚢", "Queen of Sparta", "f", { aliases: ["Helen of Troy", "Helen of Sparta", "Helene"], summary: "Daughter of Zeus and [[leda]] (or, in the Cypria, of Nemesis), hatched from an egg and reputed the most beautiful woman in the world. Carried off as a girl by Theseus and rescued by her brothers, she later chose [[menelaus]] from a crowd of suitors sworn to defend the marriage. Her departure with [[paris]], willing or not, caused the Trojan War. Homer has her back in Sparta afterwards; Stesichorus and Euripides claimed that only a phantom went to Troy while she waited in Egypt." }),
  c("clytemnestra", "Clytemnestra", "queen", "🪓", "Queen of Mycenae", "f", { aliases: ["Clytaemnestra", "Klytaimnestra"], summary: "Daughter of [[tyndareus]] and Leda, sister of Helen, and wife of [[agamemnon]], to whom she bore Iphigenia, Electra, Chrysothemis and Orestes. During the war she took [[aegisthus]] as her lover. On Agamemnon's return the pair murdered him and Cassandra; in Aeschylus she strikes the blows herself, in revenge for Iphigenia. She was killed in turn by her son Orestes." }),
  c("iphigenia", "Iphigenia", "mortal", "🦌", "Daughter of Agamemnon", "f", { aliases: ["Iphigeneia", "Iphianassa"], summary: "Eldest daughter of [[agamemnon]] and [[clytemnestra]]. When [[artemis]] held the Greek fleet at Aulis, the seer Calchas declared that only her sacrifice would release it, and she was summoned on the pretext of marriage to Achilles. In Aeschylus she dies at the altar; in the Cypria and Euripides, Artemis substitutes a deer and carries her to the land of the Taurians as her priestess, where she later saves Orestes." }),
  c("electra", "Electra", "mortal", "⚱️", "Princess of Mycenae", "f", { aliases: ["Elektra"], summary: "Daughter of [[agamemnon]] and [[clytemnestra]], unknown to Homer but central to tragedy. After her father's murder she sent her young brother [[orestes]] to safety and lived on in the palace in mourning and disgrace. When he returned she helped him kill their mother and Aegisthus, and afterwards married his friend Pylades. Aeschylus, Sophocles and Euripides each dramatized her story." }),
  c("hecuba", "Hecuba", "queen", "🐕", "Queen of Troy", "f", { aliases: ["Hekabe", "Hecabe"], summary: "Wife of [[priam]], daughter of Dymas of Phrygia in Homer or of Cisseus in Euripides, and mother of Hector, Paris, Cassandra, Troilus and many more. Before Paris' birth she dreamed of bearing a firebrand. After Troy fell she was allotted to Odysseus as a slave. In Euripides' Hecuba she blinds the Thracian king Polymestor for murdering her son Polydorus; she was finally transformed into a dog, and her grave was shown at Cynossema." }),
  c("andromache", "Andromache", "mortal", "🧺", "Wife of Hector", "f", { summary: "Daughter of Eëtion of Cilician Thebe, whose father and seven brothers were killed by Achilles, and wife of [[hector]]; their farewell in Iliad 6 is among the best-known scenes in Homer. At the fall of Troy her son [[astyanax]] was thrown from the walls and she was given to [[neoptolemus]], to whom she bore Molossus. She later married Hector's brother Helenus in Epirus." }),
  c("cassandra", "Cassandra", "seer", "🔮", "Prophetess of Troy", "f", { aliases: ["Kassandra", "Alexandra"], summary: "Daughter of [[priam]] and Hecuba. [[apollo]] granted her prophecy, and when she refused him added the curse that she would never be believed; her warnings about Paris and the Wooden Horse went unheeded. During the sack the lesser Ajax dragged her from Athena's statue. She was taken to Mycenae as [[agamemnon]]'s captive and murdered with him by Clytemnestra." }),
  c("creusa", "Creusa", "mortal", "👻", "Wife of Aeneas", "f", { aliases: ["Kreousa"], summary: "Daughter of [[priam]] and Hecuba, wife of [[aeneas]] and mother of Ascanius. In Book 2 of the [[aeneid|Aeneid]] she is separated from her family in the flight from burning Troy; when Aeneas goes back for her, her ghost tells him to go on to the western land fated for him. Earlier Greek tradition named Aeneas' wife Eurydice." }),
  c("briseis", "Briseis", "mortal", "⛺", "Captive of Achilles", "f", { aliases: ["Hippodameia"], summary: "Daughter of Briseus of Lyrnessus, captured by [[achilles]] when he sacked the city and killed her husband Mynes and her brothers. [[agamemnon]] seized her to replace his own prize Chryseis, provoking the wrath of Achilles on which the Iliad turns. She is restored, untouched as Agamemnon swears, in Book 19, where she laments the dead [[patroclus]]." }),
];

export const kingsAndSeers: EntitySeed[] = [
  c("minos", "Minos", "king", "👑", "King of Crete", "m", { summary: "Son of [[zeus]] and [[europa]], king of Knossos and lord of a sea empire. His failure to sacrifice Poseidon's bull led to the birth of the [[minotaur]], to which he fed the youths and maidens exacted from Athens in payment for his son Androgeus. He pursued Daedalus to Sicily and was killed there in his bath by the daughters of King Cocalus. Famed as a lawgiver who conversed with Zeus, he became a judge of the dead." }),
  c("rhadamanthus", "Rhadamanthus", "king", "⚖️", "Judge of the Dead", "m", { aliases: ["Rhadamanthys"], summary: "Son of [[zeus]] and [[europa]] and brother of [[minos]], proverbial for his justice and credited with the laws of Crete. Some say Minos drove him out and that he settled in Boeotia, where he married the widowed Alcmene. Homer places him in Elysium; later writers make him one of the three judges of the dead." }),
  c("sarpedon", "Sarpedon", "king", "🩸", "King of Lycia", "m", { summary: "Leader of Troy's Lycian allies. In Homer he is a son of [[zeus]] and Laodamia, daughter of Bellerophon; another tradition makes him a son of Zeus and Europa, exiled from Crete by his brother Minos. Zeus considers sparing him but yields to Hera, and he is killed by [[patroclus]]; Sleep and [[thanatos|Death]] carry his body home to Lycia. Later authors reconciled the genealogies by granting him a life of three generations." }),
  c("aeacus", "Aeacus", "king", "🗝️", "King of Aegina", "m", { aliases: ["Aiakos"], summary: "Son of [[zeus]] and the nymph [[aegina]], born on the island named for her. When it lay empty — or was emptied by a plague sent by Hera — Zeus turned its ants into men, the Myrmidons. Renowned as the most pious of the Greeks, he ended a drought by his prayers. He was father of Peleus, Telamon and Phocus, and after death became a judge and keeper of the keys of Hades." }),
  c("amphion", "Amphion", "king", "🎸", "King of Thebes", "m", { summary: "Son of [[zeus]] and [[antiope]], twin of [[zethus]], exposed at birth and raised by a herdsman. A musician with a lyre given him by Hermes, he built the walls of Thebes by charming the stones into place. He married Niobe; after Apollo and Artemis killed their children he took his own life, or was himself shot by Apollo." }),
  c("zethus", "Zethus", "king", "🧱", "Twin Brother of Amphion", "m", { aliases: ["Zethos"], summary: "Son of [[zeus]] and [[antiope]] and twin of [[amphion]], a herdsman and hunter as his brother was a musician. Together they punished Dirce, took the rule of Thebes, and fortified the lower city, Zethus hauling the stones by strength. His wife was Thebe, from whom the city was named, or in Homer Aëdon, who killed their son Itylus by mistake and became the nightingale." }),
  c("epaphus", "Epaphus", "king", "🐃", "King of Egypt", "m", { aliases: ["Epaphos"], summary: "Son of [[zeus]] and [[io]], born on the banks of the Nile after his mother's wanderings and named for the touch of Zeus that restored her. He ruled Egypt, married Memphis, daughter of the Nile, and founded the city named after her. Through his daughter Libya he was ancestor of Danaus, Aegyptus, Cadmus and Europa. Herodotus identified him with the Egyptian Apis." }),
  c("neleus", "Neleus", "king", "🏖️", "King of Pylos", "m", { summary: "Son of [[poseidon]] and Tyro and twin of [[pelias]], exposed at birth and raised by horse-herders. After quarrelling with his brother he went to Messenia and founded Pylos. When he refused to purify Heracles of the murder of Iphitus, Heracles sacked the city and killed eleven of his twelve sons, sparing only [[nestor]]." }),
  c("pelias", "Pelias", "king", "🩴", "King of Iolcus", "m", { summary: "Son of [[poseidon]] and Tyro and twin of Neleus. He seized Iolcus from his half-brother Aeson and earned Hera's hatred by killing his stepmother Sidero at her altar. Warned by an oracle against a man with one sandal, he sent [[jason]] after the Golden Fleece. On the Argonauts' return [[medea]] tricked his daughters into cutting him up and boiling him in hope of restoring his youth. He was father of Alcestis and Acastus." }),
  c("aegeus", "Aegeus", "king", "⛵", "King of Athens", "m", { aliases: ["Aigeus"], summary: "Son of Pandion and king of [[athens|Athens]]. Childless, he consulted Delphi and on the way home fathered [[theseus]] on Aethra at Troezen, leaving a sword and sandals under a rock as tokens. He later sheltered and married Medea. When Theseus' ship returned from Crete still carrying black sails, he believed his son dead and threw himself into the sea that bears his name — or, in another version, from the Acropolis." }),
  c("aeetes", "Aeëtes", "king", "🐏", "King of Colchis", "m", { aliases: ["Aeetes", "Aietes"], summary: "Son of [[helios]] and the Oceanid Perse, brother of Circe and Pasiphaë, and father of [[medea]], Chalciope and Apsyrtus. He received Phrixus and hung the [[golden-fleece|Golden Fleece]] in the grove of Ares under a dragon's guard. He set Jason to yoke fire-breathing bulls and sow dragon's teeth, and pursued the Argo when the Fleece was stolen. Later deposed by his brother Perses, he was restored by Medea." }),
  c("eurystheus", "Eurystheus", "king", "🏺", "King of Mycenae and Tiryns", "m", { summary: "Son of Sthenelus and grandson of Perseus. [[hera]] hastened his birth so that he, not [[heracles]], would inherit the lordship Zeus had promised to the next-born descendant of Perseus. He imposed the [[twelve-labors|Twelve Labours]], and was so frightened of their results that he hid in a bronze jar set in the ground and issued orders through a herald. After Heracles' death he persecuted the hero's children and was killed in Attica by Hyllus or Iolaus." }),
  c("acrisius", "Acrisius", "king", "🥏", "King of Argos", "m", { aliases: ["Akrisios"], summary: "Son of Abas and twin of Proetus, with whom he quarrelled even in the womb and eventually divided the Argolid. Told by an oracle that his daughter's son would kill him, he imprisoned [[danae|Danaë]] and later cast her and the infant [[perseus]] into the sea. Years afterwards, at funeral games in Larissa, a discus thrown by Perseus struck and killed him." }),
  c("polydectes", "Polydectes", "king", "🗿", "King of Seriphos", "m", { aliases: ["Polydektes"], summary: "Ruler of the island of Seriphos and brother of the fisherman Dictys, who had rescued [[danae|Danaë]] and her son. Wanting Danaë and finding [[perseus]] in the way, he demanded the head of [[medusa]] as a gift, expecting the youth to die. Perseus returned with it and turned the king and his court to stone, leaving Dictys to rule." }),
  c("laius", "Laius", "king", "🛣️", "King of Thebes", "m", { aliases: ["Laios"], summary: "Son of Labdacus, king of Thebes and husband of [[jocasta]]. While in exile at the court of Pelops he abducted the king's son Chrysippus, which some accounts give as the origin of the curse on his house. Warned that his son would kill him, he exposed the infant [[oedipus]] with pierced ankles. Years later he was killed by that son, a stranger to him, at a crossroads in Phocis." }),
  c("creon", "Creon", "king", "📜", "Ruler of Thebes", "m", { aliases: ["Kreon"], summary: "Son of Menoeceus and brother of [[jocasta]], who governed Thebes after the death of Laius, after the fall of Oedipus, and again after Eteocles. In Sophocles' Antigone his refusal to bury Polynices costs him his niece [[antigone]], his son Haemon and his wife Eurydice. He was father of [[megara]], wife of Heracles. He is distinct from Creon, king of Corinth, in the story of Medea." }),
  c("pentheus", "Pentheus", "king", "🌲", "King of Thebes", "m", { summary: "Son of Agave and the Sown Man Echion, grandson and successor of [[cadmus]]. In Euripides' [[bacchae|Bacchae]] he denies the divinity of his cousin [[dionysus]] and tries to suppress the new cult. The god lures him, dressed as a woman, to spy on the maenads on Mount Cithaeron, where his mother and aunts, taking him for a wild beast, tear him apart." }),
  c("midas", "Midas", "king", "🪙", "King of Phrygia", "m", { summary: "King of Phrygia, son of Gordias. For returning the lost Silenus to [[dionysus]] he was granted a wish, and asked that all he touched turn to gold; unable to eat, he washed the gift away in the river Pactolus, whose sands were gold thereafter. For preferring [[pan]]'s piping to [[apollo]]'s lyre he was given ass's ears, a secret his barber whispered into a hole and the reeds repeated. A historical Midas ruled Phrygia in the late eighth century BC." }),
  c("amphitryon", "Amphitryon", "mortal", "🛡️", "Stepfather of Heracles", "m", { summary: "Son of Alcaeus of Tiryns and grandson of Perseus. Having accidentally killed his uncle Electryon he went into exile at Thebes with Electryon's daughter [[alcmene]], and to win her waged war on the Taphians; [[zeus]] took his shape and visited her the night before he came home. He was father of Iphicles and raised [[heracles]] as his own, dying at his side in battle against the Minyans of Orchomenus." }),
  c("tyndareus", "Tyndareus", "king", "🏛️", "King of Sparta", "m", { aliases: ["Tyndareos"], summary: "King of [[sparta|Sparta]], expelled by his half-brother Hippocoön and restored by Heracles. He was husband of [[leda]] and father, or foster-father, of Helen, Clytemnestra and the Dioscuri. On Odysseus' advice he bound Helen's suitors by oath to defend her chosen husband, the pact that later raised the army against Troy. He passed the kingdom to his son-in-law [[menelaus]]." }),
  c("atreus", "Atreus", "king", "🍽️", "King of Mycenae", "m", { summary: "Son of [[pelops]] and Hippodamia and brother of [[thyestes]], with whom he contested the throne of Mycenae. When Thyestes seduced his wife Aërope and stole the golden lamb that conferred the kingship, Zeus reversed the course of the sun in Atreus' favour. Atreus then killed his brother's sons and served them to him at a feast. He was killed by [[aegisthus]]. Agamemnon and Menelaus, the Atreidae, were his sons, or in some accounts his grandsons." }),
  c("thyestes", "Thyestes", "king", "🍖", "Brother and Rival of Atreus", "m", { summary: "Son of [[pelops]] and Hippodamia. He seduced the wife of his brother [[atreus]] to gain the throne of Mycenae and was tricked in return into eating his own sons. An oracle told him that vengeance would come through a son fathered on his own daughter Pelopia; that son was [[aegisthus]], who killed Atreus. Thyestes ruled until Agamemnon and Menelaus drove him out, and died in exile on Cythera." }),
  c("aegisthus", "Aegisthus", "king", "🗡️", "Usurper of Mycenae", "m", { aliases: ["Aigisthos"], summary: "Son of [[thyestes]] by his own daughter Pelopia, exposed as an infant and suckled by a goat. Raised by Atreus, he killed him on learning his true parentage. While Agamemnon was at Troy he became the lover of [[clytemnestra]]; in Homer he is the chief murderer of the returning king. He ruled Mycenae for seven years before [[orestes]] killed him." }),
  c("laertes", "Laertes", "king", "🌳", "Father of Odysseus", "m", { summary: "Son of Arcesius, former king of Ithaca, husband of Anticleia and father of [[odysseus]]; later sources list him among the Argonauts and Calydonian hunters. In the Odyssey he has withdrawn in grief to a farm in the hills. Father and son are reunited in Book 24, where [[athena]] renews his strength and he kills Eupeithes, father of the suitor Antinous." }),
  c("memnon", "Memnon", "king", "🌅", "King of the Aethiopians", "m", { summary: "Son of [[eos]] and the Trojan prince Tithonus, and so nephew of Priam. In the lost epic Aethiopis he came to Troy's aid after Penthesilea's death, wearing armour made by Hephaestus, and killed Nestor's son Antilochus before falling to [[achilles]]. Zeus made him immortal at his mother's plea. The Greeks attached his name to the colossi at Egyptian Thebes, one of which was said to sing at dawn." }),
  c("tiresias", "Tiresias", "seer", "🦯", "Blind Prophet of Thebes", "m", { aliases: ["Teiresias"], summary: "Theban seer, son of Everes and the nymph Chariclo. He was blinded either for seeing [[athena]] bathing, or by Hera, because — having lived seven years as a woman after striking a pair of mating snakes — he sided with Zeus on the question of which sex has more pleasure in love. In recompense he received prophecy and a life of seven generations. Alone among the dead he kept his wits, and [[odysseus]] consults his shade in the Odyssey." }),
  c("calchas", "Calchas", "seer", "🐦", "Seer of the Achaeans", "m", { aliases: ["Kalchas"], summary: "Son of Thestor and chief diviner of the Greek army. At Aulis he read from a snake devouring nine sparrows that Troy would fall in the tenth year, and declared that [[artemis]] demanded the sacrifice of [[iphigenia]]. In Iliad 1 he names Agamemnon's refusal to return Chryseis as the cause of the plague. He died at Colophon after losing a contest of divination to the seer Mopsus, as had been foretold." }),

  c("agamemnon", "Agamemnon", "king", "👑", "Lord of Men", "m", { summary: "Son of [[atreus]], king of Mycenae, brother of Menelaus and commander of the Greek expedition against Troy. He sacrificed his daughter Iphigenia to gain a wind at Aulis, and his seizure of Briseis caused the quarrel with Achilles. On his return he was murdered by his wife [[clytemnestra]] and her lover Aegisthus — in Aeschylus' [[oresteia|Oresteia]], in his bath — and was later avenged by his son Orestes." }),
  c("menelaus", "Menelaus", "king", "🦰", "King of Sparta", "m", { aliases: ["Menelaos"], summary: "Son of [[atreus]], younger brother of Agamemnon and husband of [[helen]], through whom he succeeded to the throne of Sparta. In Iliad 3 he defeats Paris in single combat, only for Aphrodite to spirit his opponent away. After the sack he recovered Helen and wandered eight years, wrestling the sea-god [[proteus]] in Egypt for directions home. As Zeus' son-in-law he was promised Elysium." }),
  c("nestor", "Nestor", "king", "🧓", "The Gerenian Horseman", "m", { summary: "Son of [[neleus]] and king of Pylos, the only one of his brothers to survive Heracles' attack on the city. In youth he fought the Centaurs and raided the Eleans; at Troy, ruling over a third generation of men, he is the Greeks' elder counsellor, generous with advice and with reminiscence. He lost his son Antilochus to [[memnon]], reached home safely, and receives Telemachus in Odyssey 3." }),
  c("idomeneus", "Idomeneus", "king", "🌊", "King of Crete", "m", { summary: "Son of Deucalion and grandson of [[minos]], who led eighty Cretan ships to Troy and, though grey-haired, fought in the front rank. Homer gives him a safe return. A later tradition says that in a storm he vowed to sacrifice the first living thing he met on landing, which proved to be his son; plague followed, and he was exiled to southern Italy." }),
  c("philoctetes", "Philoctetes", "hero", "🏹", "Bearer of the Bow of Heracles", "m", { aliases: ["Philoktetes"], summary: "Thessalian archer, son of Poeas, who received the [[bow-of-heracles|bow of Heracles]] for lighting the hero's pyre. Bitten by a snake on the voyage to Troy, he was abandoned on Lemnos because of the stench of his wound. Ten years later a prophecy revealed that Troy could not fall without the bow, and he was fetched back, by Odysseus with Diomedes or, in Sophocles, Neoptolemus. Healed, he killed [[paris]]." }),
  c("neoptolemus", "Neoptolemus", "hero", "🔥", "Son of Achilles", "m", { aliases: ["Pyrrhus", "Neoptolemos"], summary: "Son of [[achilles]] and Deidamia of Scyros, brought to Troy after his father's death because the city could not be taken without him. One of the warriors in the Wooden Horse, he killed [[priam]] at the altar of Zeus and took [[andromache]] as his prize. He later married Hermione and was killed at Delphi — by Orestes, or by the priests. The Molossian kings of Epirus claimed descent from him." }),
  c("orestes", "Orestes", "hero", "⚖️", "Avenger of Agamemnon", "m", { summary: "Son of [[agamemnon]] and [[clytemnestra]], raised in Phocis with his lifelong friend Pylades. On Apollo's command he returned and killed his mother and Aegisthus, and was hounded by the [[erinyes|Erinyes]] until acquitted at Athens by Athena's casting vote, as told in Aeschylus' Eumenides. Euripides sends him to the Taurians, where he finds his sister Iphigenia alive. He ruled Mycenae and Sparta and married Hermione." }),
  c("priam", "Priam", "king", "🏰", "King of Troy", "m", { aliases: ["Priamos", "Podarces"], summary: "Son of Laomedon and the last king of [[troy|Troy]]; as a boy, then called Podarces, he alone of his brothers was spared when Heracles sacked the city. He had fifty sons, nineteen of them by [[hecuba]]. In Iliad 24 he goes by night to the tent of Achilles to ransom Hector's body. At the fall of Troy [[neoptolemus]] killed him at the altar of Zeus in his own courtyard." }),
  c("hector", "Hector", "hero", "🐎", "Breaker of Horses", "m", { aliases: ["Hektor"], summary: "Eldest son of [[priam]] and Hecuba, husband of [[andromache]], father of Astyanax, and Troy's chief defender. In the Iliad he fights Ajax to a draw, drives the Greeks back to their ships and kills Patroclus. [[achilles]] kills him before the Scaean Gate, after Athena lures him to stand by taking the form of his brother Deiphobus, and drags the body behind his chariot. The poem closes with his funeral." }),
  c("paris", "Paris", "mortal", "🍏", "Prince of Troy", "m", { aliases: ["Alexander", "Alexandros"], summary: "Son of [[priam]] and Hecuba, exposed on Mount Ida because his mother dreamed she bore a firebrand, and raised by herdsmen. In the [[judgement-of-paris|Judgement of Paris]] he awarded the golden apple to Aphrodite in return for [[helen]], and his taking her from Sparta began the Trojan War. An archer, he killed Achilles with Apollo's help, and died of a wound from Philoctetes' bow after his first love, the nymph Oenone, refused to heal him." }),
  c("helenus", "Helenus", "seer", "🔭", "Trojan Seer", "m", { aliases: ["Helenos"], summary: "Son of [[priam]] and Hecuba, twin of [[cassandra]] and the best of the Trojan augurs. After Paris' death he lost Helen's hand to Deiphobus, left the city and was captured by Odysseus, to whom he disclosed the conditions for Troy's fall. He went with Neoptolemus to Epirus, where he married [[andromache]] and ruled at Buthrotum; Aeneas visits him there in Aeneid 3." }),
  c("deiphobus", "Deiphobus", "mortal", "⚔️", "Son of Priam", "m", { aliases: ["Deiphobos"], summary: "Son of [[priam]] and Hecuba and the brother closest to [[hector]]; it is his shape Athena assumes to trick Hector into facing Achilles. After Paris died he married [[helen]]. During the sack Menelaus killed and mutilated him, and Aeneas meets his disfigured shade in the Underworld in Aeneid 6." }),
  c("troilus", "Troilus", "mortal", "🧒", "Youngest Prince of Troy", "m", { aliases: ["Troilos"], summary: "Young son of [[priam]] (or of Apollo) and Hecuba. A prophecy held that Troy would not fall if he reached the age of twenty. [[achilles]] ambushed him as he watered his horses outside the walls and killed him at the altar of Thymbraean Apollo, a scene popular with vase painters; the Iliad mentions him only as already dead. His romance with Cressida is a medieval invention." }),
  c("anchises", "Anchises", "mortal", "🦯", "Father of Aeneas", "m", { summary: "Dardanian prince and cousin of Priam. The Homeric Hymn to Aphrodite tells how [[aphrodite]], made by Zeus to desire a mortal, came to him on Mount Ida and conceived [[aeneas]]. For boasting of it he was lamed by Zeus' thunderbolt. Aeneas carried him on his shoulders from burning Troy; he died at Drepanum in Sicily, and in [[aeneid|Aeneid]] 6 his shade shows his son the future of Rome." }),
  c("laocoon", "Laocoön", "seer", "🐍", "Priest of Troy", "m", { aliases: ["Laocoon", "Laokoon"], summary: "Trojan priest of Apollo, or of Poseidon, who warned against the [[trojan-horse|Wooden Horse]] and hurled a spear into its side. Two sea serpents then came from Tenedos and killed him with his two sons — in some versions only the sons. The Trojans took it as punishment for his attack on the horse; other sources blame an earlier offence against Apollo. Virgil's account and the marble group in the Vatican made him famous." }),
  c("astyanax", "Astyanax", "mortal", "👶", "Son of Hector", "m", { aliases: ["Scamandrius", "Skamandrios"], summary: "Infant son of [[hector]] and [[andromache]], named Scamandrius by his father but called Astyanax, 'lord of the city', by the Trojans. In Iliad 6 he shrinks from his father's plumed helmet. At the fall of Troy he was thrown from the walls, by Neoptolemus or on the advice of Odysseus, so that no son of Hector should live to avenge Troy." }),
];
